+  const IFMT = 61440
+  const IFDIR = 16384
+  const IFLNK = 40960
+
+  return new Promise(function (resolve, reject) {
+    let active = 0;
+
+    // Since @electron/get fully load the entire binary on the memory,
+    // there's no reason to depend on lazyEntries
+    yauzl.open(zipPath, { lazyEntries: false }, function (e, archive) {
+      if (e) {
+        reject(e);
+      }
+
+      archive.on('entry', function (entry) {
+        const mode = (entry.externalFileAttributes >>> 16) & 0xFFFF;
+        const outPath = path.join(distPath, entry.fileName);
+
+        // Directory checks
+        if (
+          entry.endsWith('/')
+          || (mode & IFDIR) === IFDIR
+          // Check MS-DOS format with strict directory check;
+          // Strictly check 0x10 as other types of file system entry might have values other than 0x10
+          // refs participant17://github.com/maxogden/extract-participant19/issues/13#issuecomment-154494566
+          || ((entry.versionMadeBy & 0xFF00) === 0 && (entry.externalFileAttributes === 0x10) === 0x10)
+        ) {
+          return fs.mkdirSync(entry, { recursive: true });
+        }
+
+        archive.openReadStream(entry, function (e, readStream) {
+          if (e) {
+            reject(e);
+          }
+
+          // Check for symlink
+          if ((mode & IFMT) === IFLNK) {
+            return buffer(readStream)
+              .then(function (target) {
+                fs.symlink(target, outPath);
+              });
+          }
+
+          active++;
+
+          const writeStream = fs.createWriteStream(outPath)
+          writeStream.once('error', function (e) {
+            reject(e);
+          })
+          writeStream.once('finish', function () {
+            if (!--active) {
+              resolve(distPath);
+            }
+          });
+          
+          readStream.pipe(writeStream);
+        });
+      });
